//! Compatibility with real Yjs, using golden fixtures generated by `tests-compat/gen-fixtures.mjs`
//! with the Yjs release pinned in `tests-compat/package-lock.json`.
//!
//! When `YRS_COMPAT_OUT` is set, the tests also write what yrs encodes to that file, and
//! `tests-compat/check-yrs-output.mjs` decodes it with real Yjs (the other direction).

use serde_json::Value;
use std::collections::BTreeMap;
use std::sync::{Mutex, OnceLock};
use yrs::types::ToJson;
use yrs::updates::decoder::Decode;
use yrs::updates::encoder::Encode;
use yrs::{
    Any, Array, Doc, GetString, Map, OffsetKind, Options, ReadTxn, StateVector, Text, Transact,
    Update,
};

fn fixtures() -> &'static Value {
    static FIXTURES: OnceLock<Value> = OnceLock::new();
    FIXTURES.get_or_init(|| {
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/yjs-13.json");
        let json = std::fs::read_to_string(path).expect("read Yjs fixtures");
        serde_json::from_str(&json).expect("parse Yjs fixtures")
    })
}

fn fixture(name: &str) -> &'static Value {
    &fixtures()["fixtures"][name]
}

fn bytes(fixture: &Value, field: &str) -> Vec<u8> {
    let hex = fixture[field]
        .as_str()
        .unwrap_or_else(|| panic!("fixture field {} is not a string", field));
    from_hex(hex)
}

fn str_field<'a>(fixture: &'a Value, field: &str) -> &'a str {
    fixture[field]
        .as_str()
        .unwrap_or_else(|| panic!("fixture field {} is not a string", field))
}

fn from_hex(hex: &str) -> Vec<u8> {
    assert!(hex.len().is_multiple_of(2), "odd-length hex");
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("hex digit"))
        .collect()
}

fn to_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{:02x}", b)).collect()
}

/// A doc whose text offsets are UTF-16 code units, like Yjs.
fn js_doc() -> Doc {
    Doc::with_options(Options {
        offset_kind: OffsetKind::Utf16,
        ..Options::default()
    })
}

fn apply_v1(doc: &Doc, update: &[u8]) {
    let update = Update::decode_v1(update).expect("decode Yjs v1 update");
    doc.transact_mut()
        .apply_update(update)
        .expect("apply Yjs v1 update");
}

fn apply_v2(doc: &Doc, update: &[u8]) {
    let update = Update::decode_v2(update).expect("decode Yjs v2 update");
    doc.transact_mut()
        .apply_update(update)
        .expect("apply Yjs v2 update");
}

/// Records something yrs encoded, for `tests-compat/check-yrs-output.mjs` to decode with real
/// Yjs. With `check` = `"roots"`, `expect` maps root names to `{ "type", "value" }`, where type is
/// `text`, `array`, `map` or `xml` and value is what Yjs' `toJSON()`/`toString()` must return.
fn emit(name: &str, format: u8, update: &[u8], check: &str, expect: Value) {
    static OUTPUT: OnceLock<Mutex<BTreeMap<String, Value>>> = OnceLock::new();
    let Ok(path) = std::env::var("YRS_COMPAT_OUT") else {
        return;
    };
    let output = OUTPUT.get_or_init(|| Mutex::new(BTreeMap::new()));
    let mut output = output.lock().unwrap();
    output.insert(
        format!("{}_v{}", name, format),
        serde_json::json!({
            "format": format,
            "update": to_hex(update),
            "check": check,
            "expect": expect,
        }),
    );
    // Rewritten after every entry: tests run in any order and there is no "after all" hook.
    let json = serde_json::to_string_pretty(&*output).unwrap();
    std::fs::write(&path, json).expect("write YRS_COMPAT_OUT");
}

fn json_of(any: Any) -> Value {
    let mut json = String::new();
    any.to_json(&mut json);
    serde_json::from_str(&json).unwrap()
}

#[test]
fn fixtures_come_from_yjs_13() {
    let version = fixtures()["yjs"].as_str().unwrap();
    assert!(version.starts_with("13."), "fixtures from yjs {}", version);
}

#[test]
fn any_values_decode_like_yjs() {
    let f = fixture("any");
    let expected: Value = serde_json::from_str(str_field(f, "json")).unwrap();
    for (format, update) in [(1, bytes(f, "v1")), (2, bytes(f, "v2"))] {
        let doc = js_doc();
        if format == 1 {
            apply_v1(&doc, &update);
        } else {
            apply_v2(&doc, &update);
        }
        let map = doc.get_or_insert_map("m");
        let actual = json_of(map.to_json(&doc.transact()));
        assert_eq!(actual, expected, "v{}", format);
    }
}

#[test]
fn deletes_across_clients_decode_like_yjs() {
    let f = fixture("multi_client");
    for (format, update) in [(1, bytes(f, "v1")), (2, bytes(f, "v2"))] {
        let doc = js_doc();
        if format == 1 {
            apply_v1(&doc, &update);
        } else {
            apply_v2(&doc, &update);
        }
        let text = doc.get_or_insert_text("t");
        assert_eq!(
            text.get_string(&doc.transact()),
            str_field(f, "text"),
            "v{}",
            format
        );
    }
}

#[test]
fn merged_updates_are_byte_identical_to_yjs() {
    let f = fixture("merge");
    let inputs = |field: &str| -> Vec<Vec<u8>> {
        f[field]
            .as_array()
            .unwrap()
            .iter()
            .map(|h| from_hex(h.as_str().unwrap()))
            .collect()
    };
    let merged = yrs::merge_updates_v1(inputs("inputs_v1")).unwrap();
    assert_eq!(to_hex(&merged), str_field(f, "merged_v1"));
    let merged = yrs::merge_updates_v2(inputs("inputs_v2")).unwrap();
    assert_eq!(to_hex(&merged), str_field(f, "merged_v2"));
}

#[test]
fn state_vector_decodes_like_yjs() {
    let f = fixture("state_vector");
    let doc = js_doc();
    apply_v1(&doc, &bytes(f, "update_v1"));
    let sv = StateVector::decode_v1(&bytes(f, "sv")).unwrap();
    assert_eq!(sv, doc.transact().state_vector());
    assert_eq!(
        doc.get_or_insert_text("t").get_string(&doc.transact()),
        str_field(f, "text")
    );
}

#[test]
fn yrs_text_is_readable_by_yjs() {
    let doc = js_doc();
    let text = doc.get_or_insert_text("t");
    let array = doc.get_or_insert_array("a");
    {
        let mut txn = doc.transact_mut();
        text.insert(&mut txn, 0, "héllo 😀 world");
        text.remove_range(&mut txn, 1, 4);
        array.insert(&mut txn, 0, 1.5);
        array.insert(&mut txn, 1, "x");
    }
    let txn = doc.transact();
    let expected = serde_json::json!({
        "t": { "type": "text", "value": text.get_string(&txn) },
        "a": { "type": "array", "value": [1.5, "x"] },
    });
    let sv = StateVector::default();
    emit(
        "text_and_array",
        1,
        &txn.encode_state_as_update_v1(&sv),
        "roots",
        expected.clone(),
    );
    emit(
        "text_and_array",
        2,
        &txn.encode_state_as_update_v2(&sv),
        "roots",
        expected,
    );
}
